static void smp_start_secondary(void *cpuvoid)
{
 int cpu = ((*((struct lowcore *) 0)).cpu_nr);

 (*((struct lowcore *) 0)).last_update_clock = get_tod_clock();
 (*((struct lowcore *) 0)).restart_stack = (unsigned long)restart_stack;
 (*((struct lowcore *) 0)).restart_fn = (unsigned long)do_restart;
 (*((struct lowcore *) 0)).restart_data = 0;
 (*((struct lowcore *) 0)).restart_source = -1U;
 (*((struct lowcore *) 0)).restart_flags = 0;
 restore_access_regs((*((struct lowcore *) 0)).access_regs_save_area);
 cpu_init();
 rcu_cpu_starting(cpu);
 init_cpu_timer();
 vtime_init();
 vdso_getcpu_init();
 pfault_init();
 notify_cpu_starting(cpu);
 if ((cpu_topology[cpu].dedicated))
  set_cpu_flag(7);
 else
  clear_cpu_flag(7);
 set_cpu_online(cpu, true);
 update_cpu_masks();
 inc_irq_stat(CPU_RST);
 do { arch_local_irq_enable(); } while (0);
 cpu_startup_entry(CPUHP_AP_ONLINE_IDLE);
}

